import { toCliError } from "./cli/errors.js";
import { printJson } from "./cli/output.js";
import { resolveDeployAuth } from "./cli-deploy.js";
import { DeployApiError, } from "./deploy-client.js";
import { sanitizeCustomerError } from "./logs-client.js";
import { resolveProdSlug, trimNonEmpty } from "./resolve-prod-target.js";
import { isRecord } from "./is-record.js";
export const HOSTED_RUNS_LAG_NOTE = "Turn running; runs may lag behind events.";
/** Pages of the events poll. One more read confirms the list ended. */
export const HOSTED_EVENT_PAGE_CAP = 32;
export class HostedSessionEventsError extends Error {
    constructor(message) {
        super(message);
        this.name = "HostedSessionEventsError";
    }
}
export function writeHostedCommandError(error, write = (text) => {
    process.stderr.write(text);
}) {
    const raw = error instanceof Error ? error.message : String(error);
    write(`${sanitizeCustomerError(raw)}\n`);
    // The exit code still says what kind of failure it was (not found, auth, …).
    return toCliError(error).exitCode;
}
export function processOutputLines(startLog) {
    const text = (startLog ?? "").trimEnd();
    if (text.length === 0) {
        return [];
    }
    return text.split("\n");
}
export const HOSTED_TOOLS_OFF_NOTICE = "Tool names are off.";
export function hostedToolNames(events, seen = new Set()) {
    const added = [];
    for (const event of events) {
        const eventKey = `event:${event.index}`;
        if (seen.has(eventKey)) {
            continue;
        }
        seen.add(eventKey);
        const data = record(event.data);
        if (event.type === "actions.requested" && Array.isArray(data.calls)) {
            for (const call of data.calls) {
                const callRecord = record(call);
                const name = stringValue(callRecord.toolName);
                if (name === undefined) {
                    continue;
                }
                const callKey = callKeyFor(stringValue(callRecord.callId), event.index, name);
                if (seen.has(callKey)) {
                    continue;
                }
                seen.add(callKey);
                added.push(name);
            }
            continue;
        }
        if (event.type === "action.result") {
            const name = stringValue(data.toolName);
            if (name === undefined) {
                continue;
            }
            const callKey = callKeyFor(stringValue(data.callId), event.index, name);
            if (seen.has(callKey)) {
                continue;
            }
            seen.add(callKey);
            added.push(name);
        }
    }
    return added;
}
export function formatHostedSessionRuns(sessionId, runs, events) {
    const lines = [`Session ${sessionId}`, `Hosted executions: ${runs.executions.length}`];
    for (const run of runs.executions) {
        const failure = run.error?.message ?? run.message ?? "";
        lines.push("", `${run.executionId}  ${run.turnStatus}  ${run.durationMs}ms  ${run.writtenAt}  ${failure}`.trimEnd(), ...run.logs.map((log) => `  ${log.line}`));
    }
    const processOutput = processOutputLines(runs.startLog);
    if (processOutput.length > 0) {
        lines.push("", "Process output:", ...processOutput);
    }
    const latestType = events?.events.at(-1)?.type;
    if (events !== undefined && events.events.length > 0) {
        const latest = latestType === undefined ? "" : ` (latest ${latestType})`;
        lines.push("", `Events: ${events.events.length}${latest}`);
    }
    const turnRunning = runs.executions.at(-1)?.turnStatus === "running" ||
        (runs.executions.length === 0 && events?.execution?.turnStatus === "running");
    if (turnRunning && (events?.events.length ?? 0) > 0) {
        lines.push(HOSTED_RUNS_LAG_NOTE);
    }
    return `${lines.join("\n")}\n`;
}
export async function readAllHostedSessionEvents(read, pageCap = HOSTED_EVENT_PAGE_CAP, startAfter = -1) {
    const events = [];
    let after = startAfter;
    for (let page = 0; page < pageCap; page++) {
        const batch = await read(after);
        if (batch.events.length === 0) {
            return events;
        }
        const last = batch.events[batch.events.length - 1].index;
        if (last <= after) {
            throw new HostedSessionEventsError("Hosted session events stopped advancing, so the list is incomplete.");
        }
        events.push(...batch.events);
        after = last;
    }
    const tail = await read(after);
    if (tail.events.length === 0) {
        return events;
    }
    throw new HostedSessionEventsError(`Hosted session events exceed ${pageCap} pages, so the list is incomplete.`);
}
/**
 * One poll of `logs --prod`. Process output, each session tail, and tool
 * names are separate lists. Each list only grows at the end, so a follow
 * can print the new suffix instead of the whole buffer.
 */
export function enrichHostedLogSessions(args) {
    const blocks = [];
    if (args.stageLines.length > 0) {
        blocks.push(...processOutputBlocks("process-output", args.stageLines, args.scoped, "Process output:"));
    }
    if (args.startLogLines.length > 0) {
        const second = args.stageLines.length > 0;
        blocks.push(...processOutputBlocks(second ? "start-log" : "process-output", args.startLogLines, args.scoped, second ? "Session process output:" : "Process output:"));
    }
    blocks.push(...args.sessions);
    if (args.toolNames.length > 0) {
        blocks.push({
            sessionId: "tools",
            lines: args.toolNames.map((name) => `tool ${name}`),
        });
    }
    return blocks;
}
export function createHostedProdLogReader(args) {
    let eventCursor = -1;
    const seenTools = new Set();
    const toolNames = [];
    let stopTools = false;
    let notedToolsOff = false;
    const noteToolsOff = () => {
        if (notedToolsOff) {
            return;
        }
        notedToolsOff = true;
        writeHostedCommandError(new Error(HOSTED_TOOLS_OFF_NOTICE), args.writeError);
    };
    return async (signal) => {
        const sessions = await args.client.getAgentkitDeploymentLogs({
            teamId: args.teamId,
            slug: args.slug,
            sessionId: args.sessionId,
            signal,
        });
        let stageLines = [];
        try {
            const stage = await args.client.getAgentkitPersistentStageLogs({
                teamId: args.teamId,
                slug: args.slug,
                signal,
            });
            stageLines = stage.lines;
        }
        catch (error) {
            if (!isNotFound(error)) {
                throw error;
            }
        }
        const sessionId = args.sessionId;
        let startLogLines = [];
        if (sessionId !== undefined) {
            try {
                const runs = await args.client.getAgentkitSessionRuns({
                    teamId: args.teamId,
                    slug: args.slug,
                    sessionId,
                });
                startLogLines = processOutputLines(runs.startLog);
            }
            catch (error) {
                if (!isNotFound(error)) {
                    throw error;
                }
            }
            if (!stopTools) {
                try {
                    const events = await readAllHostedSessionEvents((afterEventIndex) => args.client.getAgentkitSessionEvents({
                        teamId: args.teamId,
                        slug: args.slug,
                        sessionId,
                        afterEventIndex,
                    }), HOSTED_EVENT_PAGE_CAP, eventCursor);
                    const last = events.at(-1)?.index;
                    if (last !== undefined) {
                        eventCursor = last;
                    }
                    toolNames.push(...hostedToolNames(events, seenTools));
                }
                catch (error) {
                    if (isNotFound(error) || error instanceof HostedSessionEventsError) {
                        stopTools = true;
                        noteToolsOff();
                    }
                    else {
                        throw error;
                    }
                }
            }
        }
        return enrichHostedLogSessions({
            sessions,
            stageLines,
            startLogLines,
            toolNames,
            scoped: sessionId !== undefined,
        });
    };
}
/** v2 session text, JSON, or `--events`. */
export async function readHostedSessionView(sessionId, options) {
    if (options.rawEvents === true && trimNonEmpty(options.out) !== undefined) {
        process.stderr.write("--events and --out are mutually exclusive\n");
        return 2;
    }
    const auth = await resolveDeployAuth({
        team: options.team,
        apiKey: options.apiKey,
        fetchImpl: options.fetchImpl,
    });
    if (typeof auth === "number") {
        return auth;
    }
    let slug;
    try {
        slug = resolveProdSlug(options);
    }
    catch (error) {
        return writeHostedCommandError(error);
    }
    if (trimNonEmpty(options.out) !== undefined) {
        process.stderr.write("--out writes a local trace and needs --url. For a hosted session, use --json or --events.\n");
        return 2;
    }
    try {
        if (options.rawEvents === true) {
            const events = await readAllHostedSessionEvents((afterEventIndex) => auth.client.getAgentkitSessionEvents({
                teamId: auth.teamId,
                slug,
                sessionId,
                afterEventIndex,
            }));
            process.stdout.write(`${JSON.stringify({ sessionId, events }, null, 2)}\n`);
            return 0;
        }
        const runs = await auth.client.getAgentkitSessionRuns({
            teamId: auth.teamId,
            slug,
            sessionId,
        });
        const latest = runs.executions.at(-1);
        const events = runs.executions.length === 0 || latest?.turnStatus === "running"
            ? await auth.client
                .getAgentkitSessionEvents({
                teamId: auth.teamId,
                slug,
                sessionId,
                afterEventIndex: -1,
            })
                .catch(() => undefined)
            : undefined;
        if (options.json === true) {
            printJson({ sessionId, ...runs }, { fields: options.fields });
        }
        else {
            process.stdout.write(formatHostedSessionRuns(sessionId, runs, events));
        }
        return 0;
    }
    catch (error) {
        return writeHostedCommandError(error);
    }
}
function processOutputBlocks(sessionId, lines, scoped, header) {
    const body = { sessionId, lines: [...lines] };
    if (!scoped) {
        return [body];
    }
    return [{ sessionId: `${sessionId}:header`, lines: [header] }, body];
}
function callKeyFor(callId, eventIndex, name) {
    return callId === undefined ? `event:${eventIndex}:${name}` : `call:${callId}`;
}
function stringValue(value) {
    return typeof value === "string" && value.length > 0 ? value : undefined;
}
function isNotFound(error) {
    return error instanceof DeployApiError && error.status === 404;
}
function record(value) {
    return isRecord(value) ? value : {};
}
